BEGIN; CREATE EXTENSION IF NOT EXISTS "pgcrypto";
DO $$ BEGIN CREATE TYPE shop_member_role AS ENUM ('owner','barber'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE booking_status AS ENUM ('pending','confirmed','rejected','cancelled','completed'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS barber_shops(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),owner_user_id UUID NOT NULL REFERENCES users(id),name VARCHAR(160) NOT NULL,description TEXT,address VARCHAR(500) NOT NULL,latitude DOUBLE PRECISION NOT NULL CHECK(latitude BETWEEN -90 AND 90),longitude DOUBLE PRECISION NOT NULL CHECK(longitude BETWEEN -180 AND 180),phone VARCHAR(40),specialties JSONB NOT NULL DEFAULT '[]',timezone VARCHAR(64) NOT NULL DEFAULT 'Asia/Bangkok',is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS shop_members(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),shop_id UUID NOT NULL REFERENCES barber_shops(id) ON DELETE CASCADE,user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,role shop_member_role NOT NULL DEFAULT 'barber',bio TEXT,specialties JSONB NOT NULL DEFAULT '[]',years_experience INTEGER NOT NULL DEFAULT 0 CHECK(years_experience BETWEEN 0 AND 80),is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(shop_id,user_id));
CREATE TABLE IF NOT EXISTS shop_services(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),shop_id UUID NOT NULL REFERENCES barber_shops(id) ON DELETE CASCADE,name VARCHAR(160) NOT NULL,description TEXT,duration_minutes INTEGER NOT NULL CHECK(duration_minutes BETWEEN 15 AND 480),price NUMERIC(10,2) NOT NULL CHECK(price>=0),is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(shop_id,name));
CREATE TABLE IF NOT EXISTS shop_business_hours(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),shop_id UUID NOT NULL REFERENCES barber_shops(id) ON DELETE CASCADE,day_of_week INTEGER NOT NULL CHECK(day_of_week BETWEEN 0 AND 6),open_time TIME,close_time TIME,is_closed BOOLEAN NOT NULL DEFAULT FALSE,UNIQUE(shop_id,day_of_week),CHECK(is_closed OR(open_time IS NOT NULL AND close_time IS NOT NULL AND close_time>open_time)));
CREATE TABLE IF NOT EXISTS barber_bookings(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),shop_id UUID NOT NULL REFERENCES barber_shops(id),customer_id UUID NOT NULL REFERENCES users(id),barber_member_id UUID NOT NULL REFERENCES shop_members(id),service_id UUID NOT NULL REFERENCES shop_services(id),starts_at TIMESTAMPTZ NOT NULL,ends_at TIMESTAMPTZ NOT NULL CHECK(ends_at>starts_at),status booking_status NOT NULL DEFAULT 'pending',customer_note TEXT,cancel_reason TEXT,cancelled_by_id UUID REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_booking_barber_time ON barber_bookings(barber_member_id,starts_at,ends_at);
CREATE TABLE IF NOT EXISTS shop_messages(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),shop_id UUID NOT NULL REFERENCES barber_shops(id) ON DELETE CASCADE,customer_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,sender_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,body VARCHAR(1000) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),read_at TIMESTAMPTZ);CREATE INDEX IF NOT EXISTS ix_shop_message_conversation ON shop_messages(shop_id,customer_id,created_at); COMMIT;
